css:
.d-bound{position:relative;width:300px;height:150px;display:flex;flex-direction:column;align-items:center;gap:8px;color:var(--ink)}
.d-bound-box{position:relative;width:280px;height:120px;border:1px solid var(--line);border-radius:10px;background:var(--bg);overflow:hidden}
.d-bound-arrow{position:absolute;width:6px;height:6px;border-top:1px solid var(--ink);border-right:1px solid var(--ink);opacity:0;transition:opacity .12s linear}
.d-bound-arrow[data-side="l"]{left:4px;top:50%;margin-top:-3px;transform:rotate(-135deg)}
.d-bound-arrow[data-side="r"]{right:4px;top:50%;margin-top:-3px;transform:rotate(45deg)}
.d-bound-arrow[data-side="t"]{top:4px;left:50%;margin-left:-3px;transform:rotate(-45deg)}
.d-bound-arrow[data-side="b"]{bottom:4px;left:50%;margin-left:-3px;transform:rotate(135deg)}
.d-bound-box[data-push="l"] .d-bound-arrow[data-side="l"],.d-bound-box[data-push="r"] .d-bound-arrow[data-side="r"],.d-bound-box[data-push="t"] .d-bound-arrow[data-side="t"],.d-bound-box[data-push="b"] .d-bound-arrow[data-side="b"]{opacity:1}
.d-bound-knob{position:absolute;left:8px;top:8px;width:88px;height:56px;display:grid;place-items:center;background:var(--paper);border:1px solid var(--ink);border-radius:6px;font-family:var(--mono);font-size:9px;letter-spacing:.06em;color:var(--muted);cursor:grab;touch-action:none;user-select:none;will-change:transform}
.d-bound-knob[data-drag]{cursor:grabbing;box-shadow:0 12px 24px -8px #20241e26}
.d-bound-knob:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-bound-hint{margin:0;font-family:var(--mono);font-size:9px;color:var(--faint)}

init:
root => {
  const box = root.querySelector('.d-bound');
  if (!box || box.dataset.ready) return;
  box.dataset.ready = '1';
  const frame = box.querySelector('.d-bound-box');
  const knob = box.querySelector('.d-bound-knob');
  const hint = box.querySelector('.d-bound-hint');
  const NAME = { l: '左', r: '右', t: '上', b: '下' };
  const PAD = 8;
  const W = knob.offsetWidth, H = knob.offsetHeight;
  const MAX_X = frame.clientWidth - PAD * 2 - W;
  const MAX_Y = frame.clientHeight - PAD * 2 - H;
  const IDLE = '越界位移按 0.18 折算';
  let x = MAX_X / 2, y = MAX_Y / 2, drag = null;

  function draw(animate) {
    knob.style.transition = animate ? 'transform .28s cubic-bezier(.34,1.56,.64,1)' : 'none';
    knob.style.transform = 'translate(' + x.toFixed(1) + 'px,' + y.toFixed(1) + 'px)';
  }
  function down(e) {
    if (drag) return;
    e.preventDefault();
    knob.focus({ preventScroll: true });
    knob.setPointerCapture(e.pointerId);
    knob.dataset.drag = '1';
    drag = { x0: e.clientX - x, y0: e.clientY - y };
  }
  function move(e) {
    if (!drag) return;
    let nx = e.clientX - drag.x0, ny = e.clientY - drag.y0;
    const push = { l: 0, r: 0, t: 0, b: 0 };
    if (nx < 0) { push.l = Math.min(1, -nx / 44); nx = nx * .18; }
    else if (nx > MAX_X) { push.r = Math.min(1, (nx - MAX_X) / 44); nx = MAX_X + (nx - MAX_X) * .18; }
    if (ny < 0) { push.t = Math.min(1, -ny / 44); ny = ny * .18; }
    else if (ny > MAX_Y) { push.b = Math.min(1, (ny - MAX_Y) / 44); ny = MAX_Y + (ny - MAX_Y) * .18; }
    x = nx; y = ny;
    draw(false);
    const side = Object.keys(push).sort((a, b) => push[b] - push[a])[0];
    if (push[side] > 0) {
      frame.dataset.push = side;
      hint.textContent = '顶住「' + NAME[side] + '」边 · 位移按 0.18 折算';
    } else {
      delete frame.dataset.push;
      hint.textContent = IDLE;
    }
  }
  function up() {
    if (!drag) return;
    drag = null;
    delete knob.dataset.drag;
    x = Math.max(0, Math.min(MAX_X, x));
    y = Math.max(0, Math.min(MAX_Y, y));
    draw(true);
    delete frame.dataset.push;
    hint.textContent = IDLE;
  }
  function key(e) {
    const mv = { ArrowLeft: [-12, 0], ArrowRight: [12, 0], ArrowUp: [0, -12], ArrowDown: [0, 12] }[e.key];
    if (!mv) return;
    e.preventDefault();
    const side = mv[0] < 0 && x <= 0 ? 'l' : mv[0] > 0 && x >= MAX_X ? 'r' : mv[1] < 0 && y <= 0 ? 't' : mv[1] > 0 && y >= MAX_Y ? 'b' : '';
    x = Math.max(0, Math.min(MAX_X, x + mv[0]));
    y = Math.max(0, Math.min(MAX_Y, y + mv[1]));
    draw(true);
    if (!side) return;
    frame.dataset.push = side;
    hint.textContent = '到「' + NAME[side] + '」边 · 再推就是阻力';
    clearTimeout(box._pushT);
    box._pushT = setTimeout(() => { delete frame.dataset.push; hint.textContent = IDLE; }, 900);
  }

  knob.addEventListener('pointerdown', down);
  knob.addEventListener('pointermove', move);
  knob.addEventListener('pointerup', up);
  knob.addEventListener('pointercancel', up);
  knob.addEventListener('keydown', key);
  draw(false);
}
